diff --git a/mail/themes/windows/mail/mailWindow1.css b/mail/themes/windows/mail/mailWindow1.css
index 240e6becca1..75b47e0882c 100644
--- a/mail/themes/windows/mail/mailWindow1.css
+++ b/mail/themes/windows/mail/mailWindow1.css
@@ -102,81 +102,61 @@ treechildren::-moz-tree-row(dummy, selected, focus) {
 .titlebar-button {
   border: none;
   margin: 0 !important;
-  padding: 9px 17px;
-  -moz-context-properties: stroke;
-  stroke: currentColor;
+  padding: 9px 18px;
+
+  /* Segoe Fluent Icons is the preferred font for Windows 11, and
+   * Segoe MDL2 Assets is there for windows 10. Luckily, the relevant glyphs
+   * are the same, so we can just fall back.
+   * See: https://learn.microsoft.com/en-us/windows/apps/design/style/segoe-fluent-icons-font */
+  font:
+    round(10px, env(hairline)) / 1 "Segoe Fluent Icons",
+    "Segoe MDL2 Assets"; /* stylelint-disable-line font-family-no-missing-generic-family-keyword */

   & > .toolbarbutton-icon {
-    display: inline-flex;
-    width: 12px;
-    height: 12px;
-
-    /* the 12px image renders a 10px icon, and the 10px upscaled gets rounded to 12.5, which
-     * rounds up to 13px, which makes the icon one pixel too big on 1.25dppx. Fix: */
-    @media (1.20dppx <= resolution <= 1.45dppx) {
-      .titlebar-button > .toolbarbutton-icon {
-        width: 11.5px;
-        height: 11.5px;
-      }
-    }
+    display: none;
   }

-  /* 175% dpi should result in the same device pixel sizes as 150% dpi. */
-  @media (1.70dppx <= resolution <= 1.95dppx) {
-    padding-inline: 14.1px;
+  &::before {
+    display: inline-block;
+    content: inherit;

-    & > .toolbarbutton-icon {
-      width: 10.8px;
-      height: 10.8px;
+    &:-moz-locale-dir(rtl) {
+      transform: scaleX(-1);
     }
   }

-  /* 225% dpi should result in the same device pixel sizes as 200% dpi. */
-  @media (2.20dppx <= resolution <= 2.45dppx) {
-    padding-inline: 15.3333px;
-
-    & > .toolbarbutton-icon {
-      width: 10.8px;
-      height: 10.8px;
-    }
-  }
+  &:hover {
+    color: inherit;
+    background-color: light-dark(hsla(0, 0%, 0%, 0.12), hsla(0, 0%, 100%, 0.12));

-  /* 275% dpi should result in the same device pixel sizes as 250% dpi. */
-  @media (2.70dppx <= resolution <= 2.95dppx) {
-    /* NB: todo: this should also change padding on the buttons
-     * themselves, but without a device to test this on, it's
-     * impossible to know by how much. */
-    & > .toolbarbutton-icon {
-      width: 10.8px;
-      height: 10.8px;
+    &:active {
+      background-color: light-dark(hsla(0, 0%, 0%, 0.22), hsla(0, 0%, 100%, 0.22));
     }
   }

-  @media not (prefers-contrast) {
-    &:hover {
-      background-color: light-dark(hsla(0, 0%, 0%, 0.12), hsla(0, 0%, 100%, 0.12));
-
-      &:active {
-        background-color: light-dark(hsla(0, 0%, 0%, 0.22), hsla(0, 0%, 100%, 0.22));
-      }
-    }
+  &.titlebar-close:hover {
+    color: white;
+    background-color: hsl(355, 86%, 49%);

-    &:not(:hover) > .toolbarbutton-icon:-moz-window-inactive {
-      opacity: 0.5;
+    &:active {
+      background-color: hsl(355, 82%, 69%);
     }
   }

-  :root[lwtheme-image] & {
-    -moz-context-properties: unset;
+  &:not(:hover):-moz-window-inactive::before {
+    opacity: 0.5;
   }

   @media (prefers-contrast) {
-    stroke: ButtonText;
-    background-color: Field;
-
-    &:hover {
-      stroke: SelectedItemText;
-      background-color: SelectedItem;
+    :root:not([lwtheme]) & {
+      color: ButtonText;
+      background-color: Field;
+
+      &:is(:hover, :active),
+      &.titlebar-close:is(:hover, :active) {
+        color: SelectedItemText;
+        background-color: SelectedItem;
+      }
     }
   }
 }
@@ -186,69 +166,33 @@ treechildren::-moz-tree-row(dummy, selected, focus) {
    * for Windows 11's "snap layouts" feature, see
    * DealWithWindowsAppearanceHacks */
   -moz-default-appearance: -moz-window-button-minimize;
-  list-style-image: url("chrome://messenger/skin/window-controls/minimize.svg");
-  margin-inline-end: 2px;
-
-  :root[lwtheme-image] & {
-    list-style-image: url("chrome://messenger/skin/window-controls/minimize-themes.svg");
-  }
-
+  content: "\e921"; /* ChromeMinimize */
   @media (prefers-contrast) {
-    list-style-image: url("chrome://messenger/skin/window-controls/minimize-highcontrast.svg");
+    content: "\ef2d"; /* ChromeMinimizeContrast */
   }
 }

 .titlebar-max {
   -moz-default-appearance: -moz-window-button-maximize;
-  list-style-image: url("chrome://messenger/skin/window-controls/maximize.svg");
-
-  :root[lwtheme-image] & {
-    list-style-image: url("chrome://messenger/skin/window-controls/maximize-themes.svg");
-  }
-
+  content: "\e922"; /* ChromeMaximize */
   @media (prefers-contrast) {
-    list-style-image: url("chrome://messenger/skin/window-controls/maximize-highcontrast.svg");
+    content: "\ef2e"; /* ChromeMaximizeContrast */
   }
 }

 .titlebar-restore {
   -moz-default-appearance: -moz-window-button-restore;
-  list-style-image: url("chrome://messenger/skin/window-controls/restore.svg");
-
-  &:-moz-locale-dir(rtl) {
-    transform: scaleX(-1);
-  }
-
-  :root[lwtheme-image] & {
-    list-style-image: url("chrome://messenger/skin/window-controls/restore-themes.svg");
-  }
-
+  content: "\e923"; /* ChromeRestore */
   @media (prefers-contrast) {
-    list-style-image: url("chrome://messenger/skin/window-controls/restore-highcontrast.svg");
+    content: "\ef2f"; /* ChromeRestoreContrast */
   }
 }

 .titlebar-close {
   -moz-default-appearance: -moz-window-button-close;
-  list-style-image: url("chrome://messenger/skin/window-controls/close.svg");
-
-  :root[lwtheme-image] & {
-    list-style-image: url("chrome://messenger/skin/window-controls/close-themes.svg");
-  }
-
+  content: "\e8bb"; /* ChromeClose */
   @media (prefers-contrast) {
-    list-style-image: url("chrome://messenger/skin/window-controls/close-highcontrast.svg");
-  }
-
-  @media not (prefers-contrast) {
-    &:hover {
-      stroke: white;
-      background-color: light-dark(var(--color-red-60), var(--color-red-70));
-
-      &:hover:active {
-        background-color: light-dark(var(--color-red-50), var(--color-red-60));
-      }
-    }
+    content: "\ef2c"; /* ChromeCloseContrast */
   }
 }

